param(
    [string]$ProjectPath = (Get-Location).Path,
    [switch]$SkipNpmInstall,
    [switch]$SkipChecks,
    [switch]$RunDatabaseTests
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

function Write-Step([string]$Message) {
    Write-Host "`n==> $Message" -ForegroundColor Cyan
}

function Write-Ok([string]$Message) {
    Write-Host "[OK] $Message" -ForegroundColor Green
}

function Write-Warn([string]$Message) {
    Write-Host "[WARN] $Message" -ForegroundColor Yellow
}

function Invoke-Checked {
    param(
        [Parameter(Mandatory=$true)][string]$FilePath,
        [Parameter(Mandatory=$false)][string[]]$Arguments = @(),
        [Parameter(Mandatory=$true)][string]$Label
    )
    Write-Step $Label
    & $FilePath @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "$Label failed with exit code $LASTEXITCODE"
    }
    Write-Ok $Label
}

$ProjectPath = [System.IO.Path]::GetFullPath($ProjectPath)
Write-Host "Finance Coach - Phase 10 Monetization Installer" -ForegroundColor Magenta
Write-Host "Project: $ProjectPath"

# Validate that this looks like the Finance Coach project root.
$required = @('package.json', 'src', 'supabase')
foreach ($item in $required) {
    if (-not (Test-Path (Join-Path $ProjectPath $item))) {
        throw "Project root is invalid: missing '$item'. Run this from the Finance Coach project root, or pass -ProjectPath C:\path\to\finance-coach"
    }
}

$timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backupRoot = Join-Path $ProjectPath ".phase10-backup-$timestamp"
$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) "finance-coach-phase10-$timestamp"
$zipFile = Join-Path $tempRoot 'phase10.zip'
$extractRoot = Join-Path $tempRoot 'package'
New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
New-Item -ItemType Directory -Path $extractRoot -Force | Out-Null
New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null

