$manifest = @()
foreach ($relativePath in $filesToApply) {
    $destination = Join-Path $ProjectPath $relativePath
    $existed = Test-Path -LiteralPath $destination
    $manifest += [pscustomobject]@{ path = $relativePath; existed = $existed }
    if ($existed) {
        $backupPath = Join-Path $backupRoot $relativePath
        $backupDir = Split-Path -Parent $backupPath
        New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
        Copy-Item -LiteralPath $destination -Destination $backupPath -Force
    }
}
$manifest | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $backupRoot 'manifest.json') -Encoding UTF8
Write-Ok "Backup created: $backupRoot"

Write-Step 'Applying Phase 10 files'
foreach ($relativePath in $filesToApply) {
    $source = Join-Path $extractRoot $relativePath
    $destination = Join-Path $ProjectPath $relativePath
    if (-not (Test-Path -LiteralPath $source)) {
        throw "Installer payload is missing: $relativePath"
    }
    $destinationDir = Split-Path -Parent $destination
    New-Item -ItemType Directory -Path $destinationDir -Force | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination -Force
    Write-Host "  applied $relativePath"
}
Write-Ok 'Phase 10 source changes applied'

# Preserve user secrets. Never overwrite an existing .env.
$envPath = Join-Path $ProjectPath '.env'
$envExample = Join-Path $ProjectPath '.env.example'
if (-not (Test-Path -LiteralPath $envPath) -and (Test-Path -LiteralPath $envExample)) {
    Copy-Item -LiteralPath $envExample -Destination $envPath
    Write-Warn 'Created .env from .env.example. Fill in the real RevenueCat/Supabase values before billing tests.'
} else {
    Write-Ok 'Existing .env was preserved'
}

Push-Location $ProjectPath
try {
    $npm = Get-Command npm -ErrorAction SilentlyContinue
    if (-not $npm) {
        throw 'npm was not found. Install Node.js/npm, then run this installer again.'
    }

    if (-not $SkipNpmInstall) {
        Invoke-Checked -FilePath $npm.Source -Arguments @('install') -Label 'npm install'
    } else {
        Write-Warn 'Skipped npm install'
    }

    if (-not $SkipChecks) {
        $npx = Get-Command npx -ErrorAction SilentlyContinue
        if (-not $npx) {
            throw 'npx was not found after npm setup.'
        }
        Invoke-Checked -FilePath $npx.Source -Arguments @('tsc','--noEmit') -Label 'TypeScript typecheck'
        Invoke-Checked -FilePath $npx.Source -Arguments @('expo','lint') -Label 'Expo lint'
    } else {
        Write-Warn 'Skipped TypeScript/lint checks'
    }

    $supabase = Get-Command supabase -ErrorAction SilentlyContinue
    if ($RunDatabaseTests) {
        if (-not $supabase) {
            Write-Warn 'Supabase CLI is not installed, so local migration/database tests were skipped.'
        } else {
            Write-Warn 'The next command resets the LOCAL Supabase database only.'
            Invoke-Checked -FilePath $supabase.Source -Arguments @('db','reset') -Label 'Supabase local DB reset + migrations'
            Invoke-Checked -FilePath $supabase.Source -Arguments @('test','db') -Label 'Supabase database tests'

            Write-Step 'Regenerating local Supabase TypeScript types'
            $typesPath = Join-Path $ProjectPath 'src/types/database.types.ts'
            $typesDir = Split-Path -Parent $typesPath
            New-Item -ItemType Directory -Path $typesDir -Force | Out-Null
            $generated = & $supabase.Source gen types typescript --local
            if ($LASTEXITCODE -ne 0) { throw 'Supabase type generation failed.' }
            $generated | Set-Content -LiteralPath $typesPath -Encoding UTF8
            Write-Ok 'Supabase types regenerated'
        }
    } else {
        Write-Warn 'Database reset/tests were not run automatically. Re-run with -RunDatabaseTests when local Supabase + Docker are ready.'
    }
} finally {
    Pop-Location
    Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
}

Write-Host "`n============================================================" -ForegroundColor DarkGray
Write-Host 'PHASE 10 LOCAL CODE INSTALLATION COMPLETE' -ForegroundColor Green
Write-Host '============================================================' -ForegroundColor DarkGray
Write-Host "Backup: $backupRoot"
Write-Host ''
Write-Host 'Next step:' -ForegroundColor Cyan
Write-Host '1. Do NOT manually edit/merge the Phase 10 patch.'
Write-Host '2. Come back to ChatGPT and paste this installer output.'
Write-Host '3. We will then do the interactive external setup together:'
Write-Host '   - RevenueCat premium entitlement + Offering'
Write-Host '   - Google Play subscription product'
Write-Host '   - Android RevenueCat public SDK key'
Write-Host '   - Supabase RevenueCat webhook secrets'
Write-Host '   - webhook deployment / verification'
Write-Host '   - real-device purchase, restore, trial, cancel/expire testing'
Write-Host ''
Write-Host 'Tip: after Docker + local Supabase are running, use:' -ForegroundColor Yellow
Write-Host '  powershell -ExecutionPolicy Bypass -File .\Phase10-Install.ps1 -RunDatabaseTests'
